head.b:skin:
body{
  margin:0;
  font-family:Arial, sans-serif;
  background:#f2f2f2;
  color:#111;
}

header{
  background:#d6001c;
  color:white;
  padding:15px;
  text-align:center;
}

.container{
  max-width:1100px;
  margin:auto;
  padding:15px;
  display:grid;
  grid-template-columns:2fr 1fr;
  gap:20px;
}

.card{
  background:white;
  padding:15px;
  border-radius:10px;
  margin-bottom:15px;
}

.sidebar{
  background:white;
  padding:15px;
  border-radius:10px;
}

footer{
  text-align:center;
  padding:20px;
  background:#111;
  color:white;
  margin-top:30px;
}
